INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94623, 'spa', 'Cola; extremo, cabo', 'Cola; extremo, cabo. La cola literal de un animal: el apéndice físico posterior. Moisés agarra la serpiente por la cola (Éx 4:4), Sansón ata zorras cola con cola con antorchas (Jue 15:4), e Isaías describe los cabos humeantes de dos tizones que representan reyes debilitados (Is 7:4). En español ''cola'' abarca tanto el sentido literal como el figurado, al igual que el francés ''queue'' y el alemán ''Schwanz''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94631, 'spa', 'Prostituta, ramera (sustantivo)', 'Prostituta, ramera (sustantivo): זוֹנָה como sustantivo: prostituta, ramera. El participio femenino Qal lexicalizado como sustantivo que designa a una mujer que vende servicios sexuales. Se usa con artículo, preposiciones y en cadenas constructas. Rajab la ramera (Jos 2:1, 6:17), las dos prostitutas ante Salomón (1 R 3:16) y la ''casa de la ramera'' como lugar de peligro en Proverbios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94633, 'spa', 'Infidelidad espiritual (Qal metafórico)', 'Infidelidad espiritual (Qal metafórico): ser espiritualmente infiel, ''prostituirse'' tras otros dioses. El uso profético dominante donde la idolatría de Israel se representa como traición conyugal — ''fornicar tras'' los baales (Jue 2:17, 8:27), alianzas extranjeras (Ez 16:26, 28) o prácticas paganas (Lev 17:7, 20:5). Todo el relato matrimonial de Oseas encarna esta acepción. La construcción con אַחֲרֵי (''tras'') o תַּחַת (''bajo'') señala la infidelidad espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94634, 'spa', 'Fornicar, prostituirse (Qal literal)', 'Fornicar, prostituirse (Qal literal): cometer fornicación o inmoralidad sexual en sentido físico. Prostitución real o infidelidad conyugal de una persona concreta, atestiguada en códigos legales (Lev 19:29 — profanar a una hija; Lev 21:9 — la hija de un sacerdote) y narrativa (Gn 38:24 — Tamar acusada; Jue 19:2 — la concubina del levita).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94639, 'spa', 'Hacer fornicar (Hifil)', 'Hacer fornicar (Hifil): el causativo Hifil: hacer que otro cometa fornicación, inducir a la prostitución. El agente conduce o compele a otro a la inmoralidad sexual o a la infidelidad idolátrica. Jezabel y sus ''fornicaciones'' extravían a Israel (2 Cr 21:11, 13); un padre no debe profanar a su hija haciéndola prostituta (Lev 19:29). La raíz causativa marca la culpabilidad moral de corromper a otros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94658, 'spa', 'Fornicación invertida (uso anómalo)', 'Fornicación invertida (uso anómalo): una única ocurrencia anómala en Ez 16:34 donde la forma describe la fornicación de Jerusalén como invertida — ella paga a sus amantes en vez de recibir pago. Es la culminación de la impactante inversión de Ezequiel: ''tú eres lo contrario de las demás mujeres en tu fornicación.'' Se entiende mejor como un uso intensificado del Qal que enfatiza lo aberrante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94688, 'spa', 'Ciudad judía sefelana', 'Ciudad de Judá en las tierras bajas de la Sefela, al sureste de Zora. Aparece en Josué 15:34 entre las ciudades del distrito del valle; sus habitantes reconstruyeron la Puerta del Valle de Jerusalén (Neh 3:13) y se reestablecieron allí tras el exilio (Neh 11:30). También se menciona genealógicamente en 1 Crónicas 4:18.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94689, 'spa', 'Fornicaciones, prostituciones', 'Fornicaciones, prostituciones. Plural abstracto intensivo (pluralis intensivus) que denota infidelidad sexual habitual, empleado tanto literalmente (Gn 38:24, Tamar acusada de prostitución) como metafóricamente para la traición idolátrica del pacto de Israel (Os 1:2, ''mujer de fornicaciones''; 2 R 9:22, ''fornicaciones de Jezabel''; Nah 3:4, Nínive como seductora). Variantes flexivas: absoluto זְנוּנִים, constructo זְנוּנֵי.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94697, 'spa', 'Fornicación, prostitución, infidelidad', 'Sustantivo abstracto que abarca la fornicación, la prostitución y la infidelidad, incluyendo la inmoralidad sexual literal (Os 4:11), la deslealtad política mediante alianzas extranjeras (Ez 23:27) y la apostasía religiosa a través de la idolatría (Jer 3:2, 9; 13:27; Nm 14:33). El término aparece casi exclusivamente en los textos proféticos como imagen central de la ruptura del pacto entre Israel y Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94706, 'spa', 'Rechazar, desechar (Qal) — Significado básico en Qal', 'Rechazar, desechar (Qal) — Significado básico en Qal: rechazar, repudiar o desechar, expresando repudio decisivo. Usado abrumadoramente cuando Dios rechaza a su pueblo, constituye el lamento más angustioso de los salmistas (Sal 43:2; 44:9, 23; 60:1; 74:1; 77:7; 88:14). El español ''ha rechazado'' transmite esta despedida activa y dolorosa. En Oseas 8:3 y 8:5, el sujeto cambia a Israel o al becerro de Samaria, pero la fuerza del rechazo permanece.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94708, 'spa', 'Desechar, apartar (Hifil) — Intensificación causativa en Hifil', 'Desechar, apartar (Hifil) — Intensificación causativa en Hifil: apartar o remover con fuerza, enfatizando el desplazamiento activo. Usado en Crónicas cuando Dios expulsa sacerdotes (2 Cr 11:14) y cuando Ezequías reconoce los utensilios que Acaz había profanado y ''desechado'' (2 Cr 29:19). El Hifil subraya la fuerza física del acto de expulsión, a diferencia del rechazo emocional del Qal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94725, 'spa', 'Objeto de espanto', 'Un objeto de temblor u horror: algo cuyo terrible destino hace estremecerse a los testigos. Cada aparición sigue la fórmula de llegar a ser (היה ל o נתן ל) «espanto» para las naciones, siempre en el contexto de juicio divino. El español lo traduce como espanto o horror, el francés como effroi, y el alemán como Entsetzen, captando cada uno el estremecimiento visceral que la palabra transmite. Aparece consistentemente junto a sinónimos como חֶרְפָּה (oprobio) y קְלָלָה (maldición).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94732, 'spa', 'Pequeña cantidad o lapso', 'Cantidad pequeña o medida breve que funciona adverbialmente. En Isaías 28:10, 13 transmite una pequeñez incremental en el estribillo burlón ''un poco aquí, un poco allá'', describiendo cómo la instrucción divina llega en fragmentos aparentemente triviales. En Job 36:2 denota un breve lapso de tiempo: ''espérame un poco''. La morfología diminutiva refuerza el sentido de insignificancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94735, 'spa', 'Denunciar, maldecir públicamente', 'Denunciar, maldecir públicamente. Denunciar o maldecir formalmente, especialmente en discurso profético o judicial. El encargo de Balaam de ''denunciar'' a Israel (Nm 23:7-8) emplea esta palabra para una maldición oficial respaldada por autoridad espiritual. Proverbios 24:24 la aplica a quienes declaran inocente al malvado: ellos mismos serán denunciados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94736, 'spa', 'Maldito, bajo maldición', 'Maldito, bajo maldición. Estado pasivo de estar maldito o bajo denuncia divina. El participio pasivo en Proverbios 22:14 describe la boca de la mujer ajena como fosa para el ''maldito'' por el SEÑOR, mientras que Miqueas 6:10 pregunta si la medida escasa ''maldita'' aún persiste.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94737, 'spa', 'Indignarse, enfurecerse', 'Indignarse, enfurecerse. Arder de indignación o ira feroz, típicamente referido a la ira asentada de Dios. El Salmo 7:11 retrata a Dios como juez ''indignado'' cada día, mientras que Daniel 11:30 lo extiende a un rey hostil enfurecido contra el pacto santo (Is 66:14, Zac 1:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94747, 'spa', 'Indignación, ira', 'Indignación, ira: El sentido dominante que cubre 21 de 22 apariciones: intensa indignación justa dirigida por Dios contra el pecado o las naciones enemigas. Frecuentemente en paralelo con אַף (ira), עֶבְרָה (furor) y קֶצֶף (cólera), como en Sal 69:25 y Sof 3:8 donde Dios ''derrama'' su indignación. Isaías lo usa en la expresión ''vara de mi indignación'' (10:5) e ''instrumentos de indignación'' (13:5), representando la ira como herramienta deliberada de juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94759, 'spa', 'Irritación, disgusto resentido', 'Irritación, disgusto resentido: Una única aparición en Sal 78:49, donde זַעַם aparece junto a עֶבְרָה y צָרָה en un catálogo de aflicciones enviadas contra Egipto. La evidencia multilingüe sugiere que los traductores percibieron aquí una cualidad más personalmente agraviada: no simplemente ira judicial, sino un disgusto amargo, una irritación teñida de resentimiento dolido ante la terquedad de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94762, 'spa', 'Disgusto o furia visible', 'Estar disgustado, abatido o malhumorado: un estado de agitación interna que se manifiesta visiblemente en el rostro. En Génesis 40:6 el copero y el panadero aparecen demacrados; Daniel 1:10 lo usa para un semblante preocupado y decaído. El término asciende hasta la ira abierta en 2 Crónicas 26:19, donde Uzías estalla en furia contra los sacerdotes. Proverbios 19:3 lo emplea para el resentimiento del necio contra Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94763, 'spa', 'Ira, furor, indignación', 'Ira, furor o indignación tempestuosa, ya sea de un gobernante humano, de Dios o de fuerzas naturales. Se aplica a la cólera violenta del rey Asa (2 Cr 16:10), a la ira divina (Isa 30:30, ''furor de ira''), a la furia rugiente de un rey (Prov 19:12) y al mar embravecido que se calma una vez que Jonás es arrojado por la borda (Jon 1:15). El término conecta la furia interior con manifestaciones externas de violencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94770, 'spa', 'Clamar, pedir auxilio', 'Clamar, pedir auxilio: la acepción Qal: clamar en angustia, aflicción o súplica — gritar a Dios o a otra persona pidiendo ayuda. Es el uso dominante con 60 ocurrencias, formando la columna vertebral del ciclo de liberación en Jueces: Israel clama bajo la opresión (Jue 3:9, 15; 6:6), los israelitas claman a Dios junto al Mar Rojo (Éx 2:23), y Tamar clama tras su violación (2 S 13:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94776, 'spa', 'Ser convocado, reunirse', 'Ser convocado, reunirse: la acepción Nifal: ser convocado, llamado o reunido en respuesta a un llamamiento. Cuando el Espíritu del SEÑOR viene sobre Gedeón y toca la trompeta, Abiezer ''es convocado'' tras él (Jue 6:34); los hombres de Efraín y Manasés ''son llamados'' (Jue 6:35); los hombres de la ciudad ''se reúnen'' para perseguir a los danitas (Jue 18:22-23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94778, 'spa', 'Convocar, reunir', 'Convocar, reunir: la acepción causativa Hifil: convocar, reunir o alistar gente con un propósito. Barac ''convocó'' a Zabulón y Neftalí en Cedes (Jue 4:10, 13); David ordenó a Amasa ''convocar'' a los hombres de Judá en tres días (2 S 20:4-5). El sujeto causa activamente la reunión en lugar de simplemente clamar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94800, 'spa', 'Proclamar, pregonar', 'Proclamar, pregonar: la acepción extendida del Hifil: proclamar en voz alta, anunciar o hacer que un mensaje circule con autoridad. En Jon 3:7 el rey de Nínive ''hizo proclamar'' — emitiendo un decreto real. Job 35:9 describe a los oprimidos que ''claman'' bajo el peso de la injusticia, y Zac 6:8 presenta a la figura angélica ''pregonando'' una declaración divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94819, 'spa', 'Clamor, grito de angustia — Clamor o grito nacido de la angustia, la queja o la ', 'Clamor, grito de angustia — Clamor o grito nacido de la angustia, la queja o la súplica, sentido dominante en 18 de 19 apariciones. Es el sonido del sufrimiento que exige ser escuchado: el clamor de Sodoma (Gén 18:20), el grito del Israel esclavizado que Dios ''oyó'' (Neh 9:9), el amargo lamento de Mardoqueo ante el decreto de destrucción (Est 4:1). El español ''clamor'' apunta a su carácter visceral y público.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94827, 'spa', 'Grito, alboroto — Grito fuerte o alboroto, enfatizando el volumen y la conmoción', 'Grito, alboroto — Grito fuerte o alboroto, enfatizando el volumen y la conmoción pública más que la angustia emocional. Este sentido aparece únicamente en Eclesiastés 9:17, donde ''las palabras tranquilas de los sabios son mejores que el grito del que gobierna entre necios''. Marca el cambio del sufrimiento al mero ruido, contrastando la fanfarronería con la serena autoridad de la sabiduría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94834, 'spa', 'Brea bituminosa', 'Designa la brea en tres contextos: impermeabilización de la cesta de Moisés (Éx 2:3) e imágenes proféticas de los arroyos y la tierra de Edom convertidos en brea ardiente (Is 34:9, dos veces). Las traducciones multilingües denotan uniformemente la sustancia alquitranada. El término posee una doble valencia: sellador protector y combustible apocalíptico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94835, 'spa', 'Estar en estado de vejez o experimentar el proceso de envejecer', 'Estar en estado de vejez o experimentar el proceso de envejecer. Introduce de manera característica puntos de inflexión narrativos donde el envejecimiento de un líder plantea la cuestión de la sucesión: Abraham buscando esposa para Isaac (Gn 24:1), la conquista incompleta de Josué (Jos 13:1; 23:1-2), el liderazgo declinante de Samuel que impulsa la monarquía (1 S 8:1, 5), y la vulnerabilidad de David ante el golpe de Adonías (1 R 1:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94843, 'spa', 'anciano, líder comunitario', 'Anciano, líder comunitario o cívico. Forma sustantivada en plural o constructo que designa una figura de autoridad reconocida: miembro de un consejo gobernante, jefe tribal o funcionario cívico. Es el sentido más frecuente (139 ocurrencias), presente en fórmulas como ''ancianos de Israel'' (Éx 3:16), ''ancianos de la ciudad'' (Dt 21:3) y ''ancianos de Judá'' (2 S 19:12). Estos ancianos ejercían funciones judiciales y administrativas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94844, 'spa', 'viejo, persona anciana', 'Viejo, de edad avanzada: descripción física de años cumplidos sin connotación institucional. Se usa como adjetivo (''un hombre viejo'', ''un profeta anciano'') o sustantivo (''los viejos y los jóvenes''). Génesis 18:11 describe a Abraham y Sara como ''viejos, avanzados en días'', y Génesis 19:4 habla de ''viejos y jóvenes'' entre los hombres de Sodoma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94880, 'spa', 'ancianas (femenino plural)', 'Mujeres ancianas (plural femenino), usado en la visión de Zacarías 8:4 sobre la Jerusalén restaurada, donde ''ancianos y ancianas volverán a sentarse en las calles''. Esta única ocurrencia femenina (זְקֵנוֹת) completa la imagen escatológica de longevidad pacífica: una ciudad tan bendecida que los mayores pueden sentarse tranquilos en sus espacios públicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94890, 'spa', 'Barba — La barba o mentón de un hombre, que nunca aparece en forma plural en heb', 'Barba — La barba o mentón de un hombre, que nunca aparece en forma plural en hebreo. En la ley levítica tiene significado ritual: los sacerdotes no deben rasurarla (Lev 21:5), y todo Israel no debe destruir sus bordes (Lev 19:27). Cortarla indica duelo (Is 15:2; Jer 48:37) o humillación (2 Sam 10:4-5). David fingió locura dejando que la saliva corriera por su barba (1 Sam 21:14). En el Salmo 133:2 el aceite de unción desciende por la barba de Aarón, símbolo de la bendición desbordante de la unción sacerdotal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94905, 'spa', 'Vejez', 'Vejez, específicamente como contexto vital de un hijo nacido tardíamente. Cada aparición participa en la expresión ''hijo de la vejez'' (בֶּן־זְקֻנִים o יֶלֶד זְקֻנִים), marcando a un hijo como especialmente querido por haber nacido de padres ancianos. Isaac (Gn 21:2, 7), José (Gn 37:3) y Benjamín (Gn 44:20) reciben esta designación, y cada uno se convierte en figura de extraordinaria importancia narrativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94906, 'spa', 'Vejez', 'El estado o período de la vejez, los años avanzados en la vida de una persona. El salmista suplica no ser desechado en la vejez (Sal 71:9, 18). Enmarca el alumbramiento de Sara (Gn 24:36), la decadencia de Salomón (1 R 11:4) y la enfermedad de Asá (1 R 15:23). Se asocia frecuentemente con las canas como expresión de longevidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94912, 'spa', 'Refinar, purificar', 'Refinar, purificar o destilar: el proceso de eliminar impurezas de una sustancia mediante calor o colado. En su uso literal describe el refinamiento metalúrgico del oro (Job 28:1; 1 Cr 28:18) y la plata (1 Cr 29:4). El español emplea destilar y purificar, reflejando los aspectos duales de destilación y purificación. Las formas Piel y Pual intensifican la exhaustividad del proceso, como en el Salmo 12:6 donde la plata es purificada siete veces.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94918, 'spa', 'Borde, moldura, cornisa', 'Borde, moldura, cornisa. Borde ornamental de oro, moldura o cornisa que rodea el borde superior del mobiliario del tabernáculo. Término exclusivamente cúltico-arquitectónico, aparece solo en las instrucciones de construcción del tabernáculo y su ejecución (Éx 25:11, 24-25; 30:3-4; 37:2, 11-12, 26-27). Se aplica al arca, la mesa de los panes de la proposición y el altar del incienso. La raíz posiblemente se relaciona con la idea de rodear o coronar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94923, 'spa', 'Nombre propio del descendiente davídico que sirvió como gobernador de Judá tras ', 'Nombre propio del descendiente davídico que sirvió como gobernador de Judá tras el exilio babilónico. Nieto del rey Joaquín, aparece en Esdras 2-4, Nehemías 7 y 12, Hageo 1-2 y Zacarías 4. La forma griega Ζοροβαβελ es consistente en la LXX, y las traducciones transliteran uniformemente el nombre (Zerubabel, Zorobabel, Serubbabel), subrayando su identidad singular en la literatura postexílica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94927, 'spa', 'Topónimo del Transjordán', 'Nombre propio que designa un wadi (valle de arroyo estacional) en la región del Transjordán, que sirvió como hito geográfico en la travesía de Israel por el desierto. En Números 21:12 aparece como lugar de campamento, mientras que Deuteronomio 2:13-14 marca el cruce del wadi de Zered como el momento en que se completaron los treinta y ocho años de peregrinación y la generación condenada había perecido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94928, 'spa', 'Esparcir, dispersar (personas)', 'Esparcir, dispersar (personas): el sentido profético-judicial dominante — dispersar o esparcir pueblos entre las naciones como acto de castigo divino o conquista militar (23 de 39 ocurrencias). Dios advierte: ''os esparciré entre las naciones'' (Lv 26:33); Jeremías anuncia: ''los aventaré con aventador'' (Jer 15:7); Ezequiel declara: ''os esparciré a todos los vientos'' (Ez 5:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94933, 'spa', 'Difundir, esparcir (cosas)', 'Difundir, esparcir (cosas): esparcir cosas (no personas) o difundir abstracciones (4 ocurrencias en Proverbios). La red ''tendida'' a la vista de cualquier ave es inútil (Pr 1:17); los labios del sabio ''esparcen'' conocimiento (Pr 15:7); el rey sabio ''dispersa'' a los impíos con su mirada judicial (Pr 20:8, 26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94934, 'spa', 'Arrojar con repulsión', 'Arrojar con repulsión: una sola ocurrencia discutida en Is 30:22, donde el verbo aparece en conexión con desechar plata y oro idolátricos ''como cosa inmunda''. El contexto es purgar la contaminación — arrojar objetos impuros con asco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94935, 'spa', 'Aventar (grano)', 'Aventar (grano): el sentido agrícola concreto — aventar el grano lanzándolo al aire para que el viento separe la paja (7 ocurrencias). Rut observa cómo Booz ''aventa la cebada esta noche en la era'' (Rut 3:2); Isaías describe el forraje ''aventado'' que comen buey y asno (Is 30:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94936, 'spa', 'Ser esparcido, ser dispersado', 'Ser esparcido, ser dispersado: formas pasivas Nifal y Pual — ser dispersado o esparcido (3 ocurrencias). En Ez 6:8 Dios promete un remanente ''cuando seáis esparcidos entre los países''; en Ez 36:19 Israel ya ha sido dispersado; en Job 18:15 se ''esparce'' azufre sobre la morada del impío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94942, 'spa', 'Escudriñar, examinar', 'Escudriñar, examinar: una sola ocurrencia en Sal 139:3 donde el salmista dice a Dios ''escudriñas mi senda y mi descanso'', es decir, Dios criba y examina minuciosamente cada aspecto de la vida del hablante. La extensión metafórica pasa del aventar agrícola al escrutinio investigativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94959, 'spa', 'Brazo, miembro físico (separado)', 'Brazo, miembro físico (separado): el brazo o los brazos de un ser humano como parte física del cuerpo, y de manera abrumadora su extensión metafórica: el brazo poderoso de Dios como agente de liberación, juicio y creación. La fórmula בְּיָד חֲזָקָה וּבִזְרוֹעַ נְטוּיָה (''con mano fuerte y brazo extendido'') es lenguaje fundacional del éxodo (Dt 4:34; 5:15; 26:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94979, 'spa', 'Poder, fuerza, fuerzas', 'Poder, fuerza, fuerzas: extensión metonímica al poder abstracto, la fuerza o las fuerzas militares, donde el miembro físico ya no está a la vista. Job 22:8 describe a un ''hombre de brazo'' (אִישׁ זְרוֹעַ) significando un hombre de poder o influencia; Jer 17:5 maldice al que confía en el ''brazo'' humano (es decir, la fuerza humana en vez de Dios); Dn 11:31 usa ''brazos'' (זְרֹעִים) para fuerzas militares.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (94999, 'spa', 'Espaldilla, pierna del animal', 'Espaldilla, pierna del animal: la espaldilla o pierna delantera de un animal sacrificial, un sentido anatómico especializado restringido a la ley ritual. En Nm 6:19 la espaldilla cocida del carnero se coloca en las manos del nazareo, y Dt 18:3 asigna ''la espaldilla, las dos quijadas y el estómago'' como porción del sacerdote.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95007, 'spa', 'Salir, aparecer (sol/luz) — La salida física del sol o la luz del día sobre el h', 'Salir, aparecer (sol/luz) — La salida física del sol o la luz del día sobre el horizonte, describiendo el amanecer como fenómeno natural. Este es el sentido por defecto, presente en la narrativa y la literatura sapiencial. En Génesis 32:31 el sol sale sobre Jacob tras su lucha en Peniel, y en Jueces 9:33 marca el momento para la acción militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95017, 'spa', 'Resplandecer, brillar (radiancia divina) — El resplandor radiante de la gloria o', 'Resplandecer, brillar (radiancia divina) — El resplandor radiante de la gloria o esplendor de Dios, típicamente en teofanía o promesa escatológica. Deuteronomio 33:2 lo usa cuando Yahvé amanece desde Seír, mientras Isaías 60:1 proclama ''tu luz ha salido''. El español emplea ''resplandecer'', señalando un cambio semántico de mero surgir a majestad luminosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95021, 'spa', 'Brotar (condición cutánea) — Sentido médico que describe una condición cutánea q', 'Brotar (condición cutánea) — Sentido médico que describe una condición cutánea que brota o aparece en la superficie del cuerpo, usado únicamente de la lepra que irrumpió en la frente del rey Uzías en 2 Crónicas 26:19. La imagen de algo que ''sale'' en la piel conserva la metáfora espacial central de la raíz, aunque el dominio cambia por completo de la cosmología al diagnóstico sacerdotal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95026, 'spa', 'Nombre propio portado por múltiples figuras del Antiguo Testamento, el más notab', 'Nombre propio portado por múltiples figuras del Antiguo Testamento, el más notable siendo el hijo de Judá y Tamar (Gn 38:30; 46:12), ancestro de un clan judaíta (Nm 26:20; Jos 7:1). También designa a jefes edomitas (Gn 36:13, 17, 33), ancestros levíticos (1 Cr 6:6, 26), un jefe de clan simeonita (Nm 26:13) y un adversario cusita del rey Asá (2 Cr 14:8). Las glosas multilingües transliteran uniformemente el nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95031, 'spa', 'Zerahíta (gentilicio)', 'Designación gentilicia para los descendientes de Zérah, principalmente del clan de Judá (Nm 26:20; Jos 7:17; 1 Cr 27:11, 13) y también de la rama simeonita (Nm 26:13). Siempre aparece con el artículo (hazzarchi) como sustantivo colectivo. La narrativa de Acán (Jos 7:17) lo emplea para estrechar la identificación desde la tribu hasta el clan y el hogar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95033, 'spa', 'Nombre sacerdotal teofórico', 'Nombre personal teofórico portado por sacerdotes de la línea aaronita. Atestiguado en la genealogía que va de Eleazar hasta Esdras (1 Cr 6:6, 51; Esd 7:4) y como cabeza de familia entre los exiliados retornados (Esd 8:4). Su significado — ''Yah ha resplandecido'' — lo conecta con el cognado sudarábigo ḏrḥʾl. Tanto la LXX Ζαραια como las versiones hispanas preservan el elemento teofórico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95035, 'spa', 'Aguacero, tormenta, diluvio', 'Tormenta violenta, aguacero torrencial o diluvio, que aparece con frecuencia en contextos poéticos y proféticos como figura del juicio divino o de una fuerza destructiva abrumadora. Se asocia habitualmente con el granizo (Is 28:2; 30:30) y se usa en contraste con el refugio y la sombra que Dios provee. La palabra captura la ferocidad súbita e incontrolable de la tempestad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95042, 'spa', 'Sembrar semilla, plantar', 'Sembrar semilla, plantar: la acepción activa dominante del Qal: sembrar físicamente semilla en la tierra con fines agrícolas. Abarca tanto la siembra literal de campos (Gn 26:12, ''Isaac sembró en aquella tierra y cosechó el céntuplo'') como la extensión metafórica positiva de ''plantar'' personas en una tierra (Jer 31:27, ''Sembraré la casa de Israel con semilla de hombre y de bestia'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95043, 'spa', 'Producir semilla (plantas)', 'Producir semilla (plantas): un grupo de participios en Gn 1:11-12, 29 que describen a las plantas como ''que hacen semilla'' — la capacidad auto-propagadora y seminífera de la vegetación tal como fue creada por Dios. Aquí el verbo caracteriza una propiedad botánica inherente más que un acto agrícola humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95052, 'spa', 'Ser sembrado, ser plantado', 'Ser sembrado, ser plantado: formas pasivas y estativas (Nifal, Pual, participio pasivo Qal): tierra o semilla que es sembrada o ha sido sembrada, describiendo territorio en estado de cultivo. Dt 21:4 especifica un valle ''que no ha sido arado ni sembrado''; Dt 29:23 lamenta una tierra ''no sembrada'' tras el juicio; Sal 97:11 usa la metáfora ''luz está sembrada para el justo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95055, 'spa', 'Concebir, quedar encinta', 'Concebir, quedar encinta: extensión figurada a la concepción humana: una mujer ''que produce semilla'' (Hifil) o ''es sembrada con semilla'' (Nifal) significando concebir descendencia. Lv 12:2 prescribe la purificación cuando una mujer ''concibe'' (תַּזְרִיעַ), y Nm 5:28 promete que la mujer inocente bajo el rito de los celos ''será sembrada con simiente'' — es decir, concebirá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95075, 'spa', 'Esparcir, dispersar (metáfora de diáspora)', 'Esparcir, dispersar (metáfora de diáspora): una única ocurrencia en Zac 10:9 donde Dios declara ''los sembraré entre los pueblos'', usando el esparcimiento agrícola como metáfora de la diáspora. A diferencia de la acepción 1 donde sembrar es positivo (''plantar en una tierra''), aquí sembrar significa dispersar gente entre las naciones, aunque con un propósito redentor, pues ''se acordarán de mí en tierras lejanas''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95085, 'spa', 'descendencia, linaje', 'Descendencia humana, progenie o linaje: el sentido dominante con 172 ocurrencias, abrumadoramente en contextos pactuales, genealógicos y teológicos. La ''simiente de Abraham'' (Gn 13:15-16; 22:17-18), la ''simiente de David'' (2 S 7:12), la ''simiente santa'' de la comunidad restaurada (Esd 9:2; Is 6:13). El árabe نَسْل/ذُرِّيَّة, el suajili uzao y el español ''descendencia'' seleccionan vocabulario específico de progenie.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95086, 'spa', 'semilla, grano', 'Semilla vegetal o grano literal usado para sembrar, comer o como producto agrícola: 55 ocurrencias concentradas en Génesis 1 (plantas que dan semilla), las leyes agrícolas (Lv 11:37-38; 19:19; 27:16) y pasajes narrativos dispersos. ''Hierba que da semilla'' y ''árbol que da fruto cuya semilla está en él'' (Gn 1:11-12, 29) establecen este como el sentido del orden creacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95128, 'spa', 'tiempo de siembra', 'Época de siembra, la estación o el acto de sembrar: solo 2 ocurrencias, ambas en fórmulas del calendario agrícola. ''Mientras la tierra permanezca, la sementera y la siega... no cesarán'' (Gn 8:22); ''vuestra trilla alcanzará hasta la siembra'' (Lv 26:5). Aquí זֶרַע funciona como sustantivo temporal que designa un período del año agrícola, en contraste con קָצִיר (''cosecha'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95153, 'spa', 'Rociar, arrojar (ritual)', 'Rociar, arrojar (ritual): rociadura o aspersión ritual de líquido (especialmente sangre o agua) — la acción sacerdotal dominante de lanzar sangre sacrificial desde un recipiente (מִזְרָק) contra los lados del altar. Comprende 29 de 35 ocurrencias. Fundamental en la ceremonia de ratificación del pacto (Éx 24:6, 8) y a lo largo del sacrificio levítico (Lv 1:5, 11; 3:2, 8, 13). Distinto de la aspersión delicada con el dedo (הִזָּה).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95159, 'spa', 'Esparcir, arrojar, sembrar', 'Esparcir, arrojar, sembrar: esparcir o arrojar material seco — lanzar polvo, ceniza, polvillo o semilla con un movimiento amplio de dispersión. Moisés y Aarón arrojan hollín de horno hacia el cielo (Éx 9:8, 10), Josías esparce el polvo molido de los ídolos (2 Cr 34:4), los amigos de Job echan polvo sobre sus cabezas en duelo (Job 2:12), y el labrador de Isaías siembra comino (Is 28:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95176, 'spa', 'Esposa de Amán', 'Nombre propio femenino que identifica a la esposa de Amán el agagueo en la narrativa de Ester. Aparece en dos escenas contrastantes: primero aconsejando a Amán preparar una horca para Mardoqueo (Est 5:10, 14), y luego advirtiéndole tras su humillación pública que su caída ante Mardoqueo es inevitable (Est 6:13). Su posible etimología persa («dorada») es notable entre los lexicógrafos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95177, 'spa', 'Palmo (unidad de medida)', 'Un palmo: la medida lineal desde la punta del pulgar extendido hasta la punta del meñique, aproximadamente medio codo (unos 22-23 cm). Se usa tanto para la medición cósmica divina, como cuando Dios abarca los cielos con su mano (Is 40:12), como para la construcción humana precisa, como en las dimensiones del pectoral sacerdotal (Éx 28:16; 39:9) y el reborde del altar (Ez 43:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95181, 'spa', 'Ancestro del clan', 'Nombre propio masculino que designa al antepasado de un grupo familiar en la comunidad judía postexílica. Sus descendientes aparecen en el censo de retorno (Esd 2:8; Neh 7:13), entre quienes repudiaron a sus esposas extranjeras (Esd 10:27) y como firmantes de la renovación del pacto (Neh 10:14). El nombre funciona principalmente como identificador de clan en estas listas administrativas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95185, 'spa', 'Esconder a alguien o algo', 'Esconder a alguien o algo: el Hifil causativo donde una persona oculta activamente a otra, funcionando transitivamente con complemento directo (6 ocurrencias). Centrado en actos de ocultamiento protector: Rahab escondiendo a los espías y siendo perdonada por ello (Jos 6:17, 25), Abdías escondiendo a cien profetas de YHWH en cuevas durante la persecución de Jezabel (1 R 18:4, 13), y una madre ocultando a su hijo de la masacre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95186, 'spa', 'Esconderse, refugiarse', 'Esconderse, refugiarse: las formas reflexivas Nifal y Hitpael donde una persona se oculta activamente del peligro, la detección o la exposición social. Sentido dominante (20 ocurrencias), desde Adán y Eva escondiéndose de la presencia de Dios en el Edén (Gn 3:8, 10), pasando por los cinco reyes amoritas encerrados en la cueva de Maqueda (Jos 10:16-27), hasta el joven Saúl ocultándose entre el equipaje antes de su coronación (1 S 10:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95188, 'spa', 'Ser ocultado, estar escondido', 'Ser ocultado, estar escondido: formas pasivas Nifal, Hofal y Pual que indican que el sujeto se encuentra en estado de ocultamiento o ha sido escondido por la acción de otro (7 ocurrencias). Incluye el informe de que los cinco reyes ''han sido hallados escondidos'' en la cueva (Jos 10:17), la promesa de que del azote de la lengua ''serás escondido'' (Job 5:21) y la declaración de que nada ''está oculto'' a los ojos de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95216, 'spa', 'Ocultarse o refugiarse', 'Retirarse al ocultamiento o esconderse, ya sea por seguridad o para escapar del peligro. El imperativo qal en Isaías 26:20 insta tiernamente al pueblo de Dios a refugiarse durante la ira divina. Las formas nifal describen ocultamiento físico: los espías en los montes (Jos 2:16), un profeta huyendo a un cuarto interior (1 R 22:25), soldados sirios escondiéndose (2 R 7:12). Jeremías 49:10 lo emplea teológicamente: ni Esaú puede ocultarse del juicio de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95218, 'spa', 'Río del exilio', 'Nombre de río que aparece en tres contextos de deportación (2 R 17:6; 18:11; 1 Cr 5:26). Las traducciones multilingües transliteran uniformemente el topónimo (Habor, Jabor, Chavor). El río funciona como referente geográfico del exilio asirio, un punto fijo en el mapa de la dispersión de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95219, 'spa', 'Herida, llaga, cardenal', 'Una herida, cardenal o verdugón causado por un golpe o azote, la marca visible de violencia física sobre el cuerpo. El canto autojustificatorio de Lamec (Gn 4:23) lo empareja con פֶּצַע (herida abierta), estableciendo su lugar en un vocabulario graduado de lesiones. El código legal prescribe «llaga por llaga» (Éx 21:25), mientras que Proverbios 20:30 habla de golpes que limpian el mal. Isaías 53:5 eleva el término al plano redentor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95225, 'spa', 'Varear frutos del árbol', 'Sacudir o varear frutos (especialmente aceitunas) de un árbol golpeando las ramas con una vara, según lo prescrito en Deuteronomio 24:20. El verbo captura la acción de desprender el fruto mediante golpes. Es una técnica de cosecha diferente a la recolección manual, pensada para recoger rápidamente el producto que queda en el árbol.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95228, 'spa', 'Tomar en prenda, retener como fianza', 'Tomar en prenda, retener como fianza. Tomar o retener propiedad como prenda o garantía por una deuda: el acto del acreedor de embargar la fianza del prestatario. La legislación de la Torá restringe esta práctica (Éx 22:26, devolución de mantos; Dt 24:6, prohibición sobre piedras de molino; Dt 24:17, protección de viudas), mientras los textos proféticos condenan su abuso (Am 2:8; Job 22:6; 24:3, 9) y elogian su uso justo (Ez 18:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95237, 'spa', 'destruir, arruinar (Piel)', 'Ruina activa en el tema Piel: destrucción deliberada y causativa. Cantares 2:15 muestra zorras «destruyendo» viñas; Isaías 13:5 y 54:16 hablan de devastación cósmica y del destructor formado por Dios mismo. El Piel marca un daño intensificado e intencional, más allá de la simple falla moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95238, 'spa', 'actuar corruptamente (Qal)', 'Actuar de manera corrupta u ofender en el tema Qal, describiendo corrupción moral más que destrucción física. Nehemías 1:7 emplea el infinitivo absoluto enfático: «nos hemos corrompido gravemente». Job 34:31 extiende esto a la ofensa personal contra Dios, sugiriendo una ruina ética que nace desde dentro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95239, 'spa', 'ser destruido, ser quebrantado (Nifal/Pual)', 'Ser destruido, quebrantado o arruinado en los temas pasivos Nifal y Pual: la consecuencia sufrida de la corrupción. Proverbios 13:13 advierte que quien desprecia la palabra «será destruido»; Job 17:1 lamenta «mi espíritu está quebrantado». Refleja el estado resultante y pasivo de quien ha sido deshecho.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95247, 'spa', 'Dolores de parto', 'Describe los dolores de parto en contextos literales (Cnt 8:5, dos veces) y metafóricos (Sal 7:14). El impío «concibe» y «se afana» con el mal; la madre sufre para dar a luz. Las glosas multilingües reflejan uniformemente el proceso doloroso y extenuante de alumbrar, ya sea un hijo o la maldad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95248, 'spa', 'Destruir', 'Llevar algo a la ruina total o aniquilación, particularmente reinos y estructuras sagradas. El imperativo Pael en Dn 4:23 ordena derribar el gran árbol, mientras Esd 6:12 advierte contra destruir el Templo. El Hitpaal en Dn 2:44, 6:26 y 7:14 declara el reino de Dios indestructible. Todas las traducciones convergen en el sentido de destrucción completa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95250, 'spa', 'Dañar, hacer daño', 'Causar lesión o daño físico sin implicar destrucción total. Atestiguado una vez en Dn 6:22, donde Daniel testifica que los leones ''no me hicieron daño''. Esta acepción más leve se distingue claramente del sentido más grave de ''destruir'' que la misma raíz tiene en otros pasajes del libro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95252, 'spa', 'Cuerda, soga, cordel', 'Cuerda, soga, cordel: el sentido concreto y fundamental: una cuerda, soga o cordel físico hecho de fibras trenzadas. Usado para descender personas (Jos 2:15; Jer 38:6), arrastrar piedras (2 S 17:13), atar (Job 40:25), sujetar tiendas (Is 33:20) y aparejar naves (Is 33:23). La medición que David hizo de los cautivos moabitas con cuerdas (2 S 8:2) conecta la cuerda literal con el uso como cordel de medir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95253, 'spa', 'Región, territorio, distrito', 'Región, territorio, distrito: una extensión geográfica adicional donde חֶבֶל denota un distrito, región o franja costera de territorio. Aplicado a ''la región de Argob'' en Basán (Dt 3:4, 13-14), el distrito administrativo de Salomón (1 R 4:13) y la costa filistea en Sof 2:5. Aquí la imagen del cordel de medir se ha desvanecido casi por completo, dejando un término geográfico estándar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95260, 'spa', 'Grupo, compañía de personas', 'Grupo, compañía de personas: un sentido raro pero distintivo: un grupo o compañía de personas unidas para un propósito común. Se encuentra exclusivamente en 1 S 10:5 y 10:10, describiendo al grupo de profetas que Saúl encuentra bajando del lugar alto con instrumentos musicales. La metáfora subyacente puede ser personas ''atadas'' o unidas en comunión, como si estuvieran ligadas por una cuerda común.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95262, 'spa', 'Porción asignada, herencia', 'Porción asignada, herencia: la extensión metafórica a una porción o herencia de tierra asignada, derivada de la práctica de medir territorio con un cordel de agrimensor. En Dt 32:9, Israel es llamado ''la porción (חֶבֶל) de su heredad'', donde el cordel de medir se convierte en metonimia de lo que mide. Jos 17:5 y 17:14 lo usan para las asignaciones tribales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95282, 'spa', 'Dolor, dolores de parto', 'Dolor o angustia, especialmente la agonía aguda y rítmica del parto, empleado casi exclusivamente en textos proféticos como metáfora de sufrimiento nacional o escatológico intenso. La metáfora tiene un doble filo: el dolor de parto señala tanto la crisis como la liberación inminente. En Job se usa tanto literalmente para animales que paren como figuradamente para la calamidad humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95292, 'spa', 'Daño o perjuicio', 'Designa daño en tres contextos: perjuicio fiscal al rey (Esd 4:22), ausencia de daño físico en el horno (Dn 3:25) y liberación de toda lesión en el foso de los leones (Dn 6:23). Las glosas multilingües abarcan los ámbitos financiero y corporal. La palabra evoca amenaza y liberación: lo que podría dañar pero no lo hace, o lo que dañará si no se detiene.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95293, 'spa', 'Prenda o garantía', 'Se refiere a la prenda tomada como garantía en tres pasajes de Ezequiel (Ez 18:12, 16; 33:15). El justo la restituye; el impío no. Las glosas multilingües reflejan uniformemente la práctica jurídico-económica de retener una fianza. La palabra evoca las exigencias éticas del préstamo: no explotar al vulnerable reteniendo lo que debe ser devuelto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95295, 'spa', 'Marinero o piloto', 'Marinero o piloto de navío, etimológicamente ''manejador de cuerdas'', designando a alguien diestro en operaciones marítimas. En Ezequiel 27:8, 27-29 describe a los marineros profesionales de Tiro; en Jonás 1:6 el compuesto רַב הַחֹבֵל designa al capitán. La evidencia multilingüe (español ''pilotos'', alemán ''Schiffer'') apunta consistentemente a navegantes experimentados y no a meros pasajeros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95299, 'spa', 'abrazar a una persona', 'El sentido primario de estrechar a una persona entre los brazos como expresión de saludo, amor o reencuentro. El Piel intensifica la acción en las narrativas patriarcales: Labán corre a abrazar a Jacob (Gn 29:13), Esaú se echa al cuello de Jacob y lo abraza (Gn 33:4), e Israel abraza a Efraín y Manasés (Gn 48:10). El ciclo de Eliseo usa el participio Qal para la sunamita sosteniendo a su hijo prometido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95303, 'spa', 'cruzar las manos', 'Uso idiomático especializado en Eclesiastés 4:5 donde el necio ''cruza sus propias manos'', es decir, se cruza de brazos y no hace nada, consumiendo su propia carne por pereza. La evidencia de traducción diverge marcadamente del sentido 1: el español usa ''cruza'' en vez de ''abraza'', y el inglés ''folding'' en vez de ''embracing'', señalando un sentido figurado distinto de inacción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95312, 'spa', 'El estado básico de estar unido o conectado — el participio pasivo Qal y las for', 'El estado básico de estar unido o conectado — el participio pasivo Qal y las formas Pual que describen cosas ya sujetas o unidas. Las cortinas del tabernáculo están ''unidas una con otra'' (Éx 26:3); las hombreras del efod están ''unidas en sus dos extremos'' (Éx 28:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95313, 'spa', 'Unión física activa — la raíz Piel que significa conectar, sujetar o fijar objet', 'Unión física activa — la raíz Piel que significa conectar, sujetar o fijar objetos deliberadamente. Donde el sentido 1 describe el estado de estar unido, este sentido capta la acción de unir: Moisés ''unió'' las cortinas (Éx 36:10), y se manda a los artesanos ''unirás'' (Éx 26:6, 9, 11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95316, 'spa', 'Lanzar hechizos o atar encantamientos mágicos — el participio Qal חֹבֵר en la fr', 'Lanzar hechizos o atar encantamientos mágicos — el participio Qal חֹבֵר en la frase específica חֹבֵר חֲבָרִים, ''el que ata ataduras'', es decir, un hechicero. En Deuteronomio 18:11 aparece en el catálogo de prácticas ocultas prohibidas, y en el Salmo 58:5 el ''encantador'' es comparado con un encantador de serpientes cuyas conjuras caen en oídos sordos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95318, 'spa', 'Formar alianzas o asociaciones — el reflexivo Hitpael y ciertos usos Qal/Piel co', 'Formar alianzas o asociaciones — el reflexivo Hitpael y ciertos usos Qal/Piel con objetos personales, que significan aliarse con otro o unir fuerzas. Los cinco reyes ''se aliaron'' en el Valle de Sidim (Gn 14:3); Josafat ''se asoció'' con Ocozías de Israel en una desastrosa empresa naval (2 Cr 20:35-37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95328, 'spa', 'Componer o reunir palabras en un discurso — una única aparición cohortativa Hifi', 'Componer o reunir palabras en un discurso — una única aparición cohortativa Hifil en Job 16:4, donde Job imagina ensartar argumentos contra sus amigos: ''Yo podría unir palabras contra vosotros.'' La metáfora extiende el ''atar juntos'' físico hacia la composición retórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95333, 'spa', 'Asociación, compañía', 'Una compañía, asociación o grupo de personas unidas por un propósito o vivienda común. En Proverbios 21:9 y 25:24, «casa de compañía» (בֵּית חָבֶר) significa una casa compartida: mejor vivir en un rincón del tejado que compartir casa con una esposa pendenciera. En Oseas 6:9 describe una cuadrilla de sacerdotes que emboscan viajeros camino a Siquem.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95334, 'spa', 'Hechizo, encantamiento', 'Un hechizo, encantamiento o conjuro mágico que ata o une fuerzas sobrenaturales para lograr un efecto deseado. Deuteronomio 18:11 sitúa al «hacedor de חֶבֶר» junto a nigromantes y adivinos en una prohibición exhaustiva de prácticas ocultas. El Salmo 58:5 describe a la cobra sorda que no obedece la voz de los encantadores por hábil que sea el conjuro. Isaías 47:9 y 47:12 ridiculizan los hechizos de Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95339, 'spa', 'Heber (nombre propio)', 'Heber el ceneo, esposo de Jael, descendiente del suegro de Moisés, Hobab. Se había separado del grupo ceneo principal y acampaba cerca de Cedes de Neftalí (Jue 4:11, 17). Su neutralidad política entre Jabín de Hazor e Israel prepara el escenario dramático para el acto decisivo de Jael (Jue 4:21; 5:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95343, 'spa', 'Compañero o asociado', 'Se refiere a los compañeros de Daniel (Ananías, Misael, Azarías) en tres contextos de crisis y oración (Dn 2:13, 17, 18). Las glosas multilingües reflejan uniformemente asociación y camaradería. La palabra evoca el riesgo compartido y el apoyo mutuo: aquellos unidos por las circunstancias y por el pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95344, 'spa', 'Compañero, asociado', 'Un colega, compañero o asociado — alguien unido por rango, vocación o relación pactual compartida. El Salmo 45:7 sitúa al rey por encima de sus ''compañeros'' (חֲבֵרֶיךָ), enfatizando pares de igual dignidad. En Eclesiastés 4:10 la palabra subraya el valor práctico de la compañía: si uno cae, su compañero lo levanta. Proverbios 28:24 la emplea para referirse al cómplice desleal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95350, 'spa', 'Unidos, vinculados', 'Usado adjetivalmente para describir personas unidas o congregadas como un solo cuerpo. La única aparición en Jueces 20:11 retrata a todo Israel reunido contra Guibeá ''unidos como un solo hombre'' (כְּאִישׁ אֶחָד חֲבֵרִים). El español ''unidos'' y el inglés ''united'' captan la fuerza cohesiva de este sentido, que conserva el significado central de la raíz verbal de atar o unir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95359, 'spa', 'Hebrón (ciudad)', 'Hebrón (ciudad): el nombre propio de la antigua ciudad en las tierras altas de Judá, asociada con el asentamiento de Abraham junto a los encinos de Mamre (Gn 13:18), la cueva sepulcral de Macpela (Gn 23) y la primera capital real de David (2 S 2:1-4; 5:1-5). Sus 61 ocurrencias abarcan la narrativa patriarcal, los relatos de conquista (Jos 10:3-5), las asignaciones tribales (Jos 14:13-14) y la historia davídica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95367, 'spa', 'Hebrón (nombre propio)', 'Nombre propio levítico: hijo de Coat, nieto de Leví y antepasado epónimo del sub-clan hebronita (חֶבְרוֹנִי) dentro de los coatitas. Registrado en Éxodo 6:18, Números 3:19 y 1 Crónicas 6:2, 18; 15:9; 23:12, 19. Su clan contaba con 2.700 jefes de familia y recibió funciones de supervisión en la administración de David (1 Cr 26:30-32). Homónimo de la ciudad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95370, 'spa', 'Hebronita (gentilicio)', 'Adjetivo gentilicio para el clan levítico descendiente de Hebrón hijo de Coat. Aparece en las listas censales levíticas (Nm 3:27; 26:58) y en la organización administrativa de David, donde los hebronitas sirvieron como supervisores de asuntos religiosos y civiles a ambos lados del Jordán (1 Cr 26:23, 30, 31). Siempre se emplea con artículo como designación colectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95374, 'spa', 'Unión de cortinas', 'Pieza de acoplamiento o costura —el borde donde dos conjuntos de cortinas del tabernáculo se sujetan mutuamente mediante lazadas y broches. Las cuatro apariciones se encuentran en las instrucciones de construcción del tabernáculo (Éx 26:4, 10; 36:17), describiendo el proceso técnico de unir los paneles de cortina para formar una cubierta completa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95375, 'spa', 'Ensillar un animal', 'Ensillar un animal: el sentido más frecuente (13 ocurrencias), que abarca toda la tradición narrativa. Abraham ensilla su asno para el viaje al Moriah (Gn 22:3), Balaam para su fatídico trayecto (Nm 22:21), el levita para su trágico viaje a Guibeá (Jue 19:10), el siervo de Mefiboset, Siba, ensilla asnos cargados de provisiones (2 S 16:1) y Ahitofel ensilla el suyo antes de su suicidio (2 S 17:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95377, 'spa', 'Atar, sujetar', 'Atar, sujetar: atar o sujetar en sentido general (4 ocurrencias). En Levítico 8:13, Moisés ata las mitras a los hijos de Aarón durante la investidura sacerdotal. Job 40:13 ordena atar rostros en el polvo (humillación). Ezequiel 24:17 instruye al profeta a no atarse el turbante (prohibición de duelo), y Ezequiel 27:24 describe a los mercaderes de Tiro atando cuerdas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95379, 'spa', 'Vendar heridas', 'Vendar heridas: vendar heridas, curar la quebradura — 12 ocurrencias que abarcan tanto el cuidado médico literal como la metáfora profética. Job 5:18 declara que Dios ''hiere pero también venda''; Salmo 147:3 celebra a Dios como quien ''venda a los quebrantados de corazón''; Isaías 1:6 lamenta heridas ''no vendadas''; y Oseas 6:1 confía en que Dios ''nos vendará''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95387, 'spa', 'Detener, represar', 'Detener, represar: represar o contener (agua) — una sola ocurrencia en Job 28:11, donde el minero ''detuvo'' las fuentes de los ríos para exponer tesoros ocultos. El salto metafórico de atar un objeto a bloquear un curso de agua es natural: la misma acción física de asegurar y contener, aplicada al agua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95396, 'spa', 'Gobernar, dominar', 'Gobernar, dominar: gobernar o poner bajo control — una sola ocurrencia en Job 34:17, en la pregunta retórica de Elihú: ''¿Gobernará el que aborrece el derecho?'' La trayectoria semántica de ''atar'' a ''gobernar'' pasa por el concepto de sujeción y control: un gobernante ''ata'' a un pueblo bajo su autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95399, 'spa', 'Envolver, ceñir', 'Envolver, ceñir: envolver o ceñir con tela (2 ocurrencias), donde el énfasis recae en rodear más que en simplemente atar. En Ezequiel 16:10, Dios recuerda con ternura haber envuelto a la Jerusalén recién nacida en lino fino; en Jonás 2:5, las algas marinas ''se envolvieron'' alrededor de la cabeza del profeta en las profundidades del mar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95403, 'spa', 'Fiesta, festividad de peregrinación', 'Fiesta, festividad de peregrinación: el sentido principal que designa una fiesta sagrada o festividad de peregrinación, especialmente las tres fiestas anuales de peregrinaje ordenadas en la Torá (Éx 23:14-17; Dt 16:14). El cognado árabe حَجّ conserva el matiz original de peregrinación. Abarca 61 de las 62 ocurrencias, incluyendo fiestas a YHWH, festivales idolátricos y celebraciones futuras escatológicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95425, 'spa', 'Sacrificio festivo, ofrenda de la fiesta', 'Sacrificio festivo, ofrenda de la fiesta: un único uso metonímico en Sal 118:27 donde el término pasa del evento festivo al sacrificio festivo u ofrenda misma — la víctima atada con cuerdas a los cuernos del altar. El contexto claramente requiere la ofrenda concreta en lugar de la celebración abstracta, una extensión semántica reconocida en las lenguas semíticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95427, 'spa', 'Langosta o saltamontes', 'Un insecto pequeño del tipo langosta o saltamontes, probablemente una especie no voladora incluida entre los insectos puros en Lv 11:22. Se usa frecuentemente como figura de insignificancia o pequeñez, como en el lamento de los espías en Nm 13:33 y la perspectiva cósmica divina en Is 40:22. En 2 Cr 7:13 funciona como agente de plaga agrícola que Dios envía en juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95431, 'spa', 'Celebrar una fiesta — Observar, guardar o celebrar un festival religioso o fiest', 'Celebrar una fiesta — Observar, guardar o celebrar un festival religioso o fiesta de peregrinación. Usado para las observancias prescritas del calendario de Israel, el verbo porta el sentido cognado árabe de ''hacer peregrinación'' (cf. hajj). El español usa consistentemente ''celebrar''. Pasajes clave incluyen el mandato de las tres fiestas (Éx 23:14), la institución de la Pascua (Éx 12:14) y la observancia de Sucot (Lev 23:39).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95443, 'spa', 'Tambalearse, vacilar — Tambalearse, oscilar o moverse de forma inestable, descri', 'Tambalearse, vacilar — Tambalearse, oscilar o moverse de forma inestable, describiendo el movimiento desvalido de marineros sacudidos por la tormenta en el Salmo 107:27. El español capta esto con ''temblaban''. La conexión con el sentido festivo puede residir en el movimiento giratorio y circular de la danza asociada a la celebración, aquí transferido al bamboleo involuntario de quienes están en el mar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95444, 'spa', 'Hendiduras de la roca', 'Se refiere a grietas en la roca como lugares de refugio u ocultamiento en tres contextos: la amada resguardada en seguridad (Cnt 2:14) y la arrogante confianza de Edom en fortalezas montañosas (Jer 49:16; Abd 3). Las glosas multilingües denotan uniformemente fisuras estrechas. La palabra evoca tanto el refugio protector como la falsa seguridad, según quién busque amparo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95447, 'spa', 'Cinturón o taparrabos', 'Un cinturón, ceñidor o taparrabos usado alrededor de la cintura. En Gn 3:7 se refiere a las coberturas improvisadas de hojas de higuera, la prenda más básica de recato. Como equipo militar (2 S 18:11; 1 R 2:5; 2 R 3:21), es el cinturón del guerrero al que se sujetan las armas. También aparece entre artículos de refinamiento femenino en Is 3:24, que serán arrancados como señal de juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95448, 'spa', 'Nombre y gentilicio', 'Funciona como nombre propio (Gn 46:16) y como gentilicio (Nm 26:15, dos veces). Las traducciones multilingües (Haggi, Hagui, haguita) reflejan tanto al individuo como al clan. El nombre evoca el patrón más amplio de la genealogía israelita: de patriarca a tribu y de tribu a clan, donde cada nombre es un hilo en el linaje del pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95449, 'spa', 'Hageo (nombre propio)', 'Nombre personal del profeta postexílico, derivado de la raíz hebrea que significa ''fiesta'' o ''festival'', lo que sugiere que pudo haber nacido en un día sagrado. Sus nueve apariciones se concentran en Hageo 1-2, donde ''vino palabra de YHWH por medio del profeta Hageo'' es una fórmula recurrente (Hag 1:1, 3; 2:1, 10). En español se traduce como ''Hageo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95452, 'spa', 'Nombre propio: Jaguit', 'El nombre propio de la esposa de David y madre de Adonías, derivado de la raíz חַג que significa ''fiesta''. Las cinco apariciones la identifican en conexión con el linaje de Adonías y su intento de tomar el trono. Las traducciones al español la transcriben como ''Jaguit'' o ''Haguit''. La forma de la LXX, Angit, refleja una tradición de pronunciación variante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95453, 'spa', 'Hija de Zelofehad', 'Nombre propio femenino que identifica a una de las cinco hijas de Zelofehad de la tribu de Manasés. Sus apariciones abarcan la lista censal (Nm 26:33), la histórica petición de herencia (Nm 27:1), la normativa de matrimonio dentro de la tribu (Nm 36:11) y la asignación de tierras en Cisjordania (Jos 17:3). El nombre probablemente significa «perdiz», según señala BDB.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95454, 'spa', 'Ceñir, atar alrededor', 'Ceñir, atar alrededor: ceñir o atar algo alrededor del cuerpo — el sentido activo transitivo que abarca el ceñimiento de cilicio en el duelo, la sujeción de espadas para la batalla y la colocación de vestiduras sacerdotales para el servicio. Moisés ciñe a Aarón y a sus hijos (Lv 8:7, 13), Ehud ata una daga a su muslo (Jue 3:16) y David se ciñe su espada (1 S 25:13). La instrucción pascual de comer ''ceñidos los lomos'' (Éx 12:11) encarna la postura de alerta y disposición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95455, 'spa', 'Ceñido, equipado (estativo)', 'Ceñido, equipado (estativo): el sentido estativo o resultativo — estar ceñido, llevar algo atado al cuerpo, expresado mediante formas participiales y pasivas. Los guerreros danitas están ''ceñidos con armas de guerra'' (Jue 18:11, 16, 17), David ministra ''ceñido con un efod de lino'' (1 S 2:18; 2 S 6:14), y la Pascua se come ''con los lomos ceñidos'' en disposición para la marcha (Éx 12:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95481, 'spa', 'Salir temblando (lectura disputada)', 'Salir temblando (lectura disputada): una ocurrencia debatida en 2 Samuel 22:46 (paralelo Sal 18:46) donde el texto es incierto. La forma masorética podría derivar de חָגַר (''ceñir'', es decir, ''salir temblando de sus fortalezas'') o reflejar una variante textual relacionada con חָרַג (''temblar, salir con temor''). Las traducciones divergen — ''saldrán temblando'' — sugiriendo el sentido de ''salir temeroso o tembloroso de un refugio''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95486, 'spa', 'Uno', 'El numeral cardinal ''uno'', usado como adjetivo o sustantivo en contextos legales y narrativos arameos. Aparece en decretos oficiales (Esdras 4:8; 6:2-3), la interpretación del sueño de Nabucodonosor (Daniel 2:9) y las visiones simbólicas de Daniel. La forma es cognada del hebreo אֶחָד y funciona de manera idéntica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95489, 'spa', 'Juntos, como uno', 'Una extensión adverbial que significa ''juntos, como uno solo'', donde el numeral transmite acción unificada simultánea en vez de simple conteo. En Daniel 2:35, el hierro, el barro, el bronce, la plata y el oro se quiebran todos ''juntos'' (כַּחֲדָה) y se vuelven como tamo. El español ''juntamente'' capta el matiz colectivo de este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95490, 'spa', 'Afilado o cortante', 'Afilado o agudo, describiendo una hoja o, figuradamente, una lengua o boca como peligrosamente cortante. Se usa literalmente de una espada o navaja en Ezequiel 5:1, y metafóricamente del habla en Salmo 57:4 (la lengua como espada afilada), Isaías 49:2 (la boca del siervo como hoja aguzada) y Proverbios 5:4 (el desenlace de la adúltera es ''agudo como espada de dos filos'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95491, 'spa', 'Ser afilado o aguzado', 'Ser afilado o aguzado, describiendo un arma preparada para uso mortal o, por extensión, ferocidad depredadora. Tres de las cuatro apariciones se concentran en Ezequiel 21:9-11 (hofal pasivo: ''la espada está afilada, afilada y pulida''), formando un estribillo de juicio divino inminente. La cuarta, en Habacuc 1:8 (qal: ''más feroces que lobos nocturnos''), aplica el concepto a la aterradora rapidez de la caballería caldea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95494, 'spa', 'Regocijarse, alegrarse', 'Describe el regocijo en tres contextos: la alegría de Jetro por la liberación de Israel (Ex 18:9), la exclusión del gozo del día del nacimiento de Job (Job 3:6), y Dios que llena de alegría al rey (Sal 21:6). Las glosas multilingües (rejoiced, se alegró, se réjouir) reflejan un gozo exuberante. La palabra evoca respuesta al favor divino o a su ausencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95499, 'spa', 'Topónimo postexílico', 'Topónimo que aparece en tres listas postexílicas (Esd 2:33; Neh 7:37; Neh 11:34), siempre agrupado con Lod y Ono. Las glosas multilingües transliteran uniformemente el nombre (Hadid, Jadid). La ciudad funciona como punto de referencia del reasentamiento en la provincia de Benjamín, un lugar fijo en el mapa de la Judá restaurada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95500, 'spa', 'Desistir, abstenerse de', 'Desistir, abstenerse de: desistir o abstenerse de hacer algo — restricción voluntaria, normalmente con la preposición מִן especificando la acción abandonada. Las 16 ocurrencias se centran en decisiones morales o prácticas de contenerse. Los árboles de Jotam rechazan el reinado: el olivo dice ''¿acaso cesaré de mi aceite?'' (Jue 9:9); la higuera y la vid repiten el rechazo (9:11, 13). Dt 23:22 advierte contra hacer un voto y luego ''abstenerse'' de cumplirlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95502, 'spa', 'Cesar, terminar', 'Cesar, terminar: cesar o llegar a su fin — cesación intransitiva de una acción, estado o fenómeno natural. La acepción dominante con 23 ocurrencias. El granizo ''cesó'' (Éx 9:29, 33), el maná ''cesó'' (Jos 5:12) y se dejó de contar el grano porque era inmenso (Gn 41:49). El sujeto se detiene por su propia naturaleza, sin que medie una decisión deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95503, 'spa', 'Dejar en paz, dejar tranquilo', 'Dejar en paz, dejar tranquilo: dejar en paz o dejar ser — un sentido imperativo o yusivo de desistir, dirigido a menudo a Dios o a un superior. Las 16 ocurrencias llevan el tono de ''¡deja de molestar!'' o ''¡retírate!''. Moisés dice a los israelitas ''¡déjanos!'' (Éx 14:12); Job suplica a Dios que ''aparte su mirada y me deje en paz'' (Job 7:16; 10:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95525, 'spa', 'Faltar, carecer', 'Faltar, carecer: faltar, carecer o dejar de existir — un sentido estativo que denota la ausencia de algo esperado. Cuatro ocurrencias en los márgenes del rango semántico del verbo. ''No cesarán los pobres de la tierra'' (Dt 15:11), ''los impíos cesan de perturbar'' en la muerte (Job 3:17), una persona ''cesa de obrar sabiamente'' (Sal 36:3) y ''en las muchas palabras no cesa la transgresión'' (Pr 10:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95549, 'spa', 'Efímero y desamparado', 'Describe lo que cesa, es transitorio o es desamparado en tres contextos: la brevedad de la vida humana (Sal 39:4), el Siervo rechazado por los hombres (Is 53:3), y el que rehúsa escuchar (Ez 3:27). Las glosas multilingües (transient, frágil, abandonner, cesser) reflejan tanto la fugacidad temporal como el abandono social. La palabra evoca vulnerabilidad y ausencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95554, 'spa', 'Cuarto, cámara interior', 'Cuarto, cámara interior: una habitación o cámara interior dentro de una estructura mayor, que enfatiza la privacidad, el recogimiento y la retirada del espacio público. Se usa para dormitorios (Jue 15:1; 2 S 13:10; 1 R 1:15), escondites (Jue 16:9, 12; 1 R 20:30; 22:25) y metafóricamente para rincones ocultos — ''lo más profundo del vientre'' (Pr 18:8; 20:30). Deuteronomio 32:25 lo contrapone al exterior: ''de fuera la espada, y de dentro el terror''. Las ''cámaras del sur'' (Job 9:9) extienden la imagen a recónditos recesos celestiales, mientras que Proverbios advierte que la casa de la seductora conduce a ''las cámaras de la muerte'' (7:27). Isaías ordena a Israel: ''entra en tus aposentos y cierra tus puertas'' hasta que pase la indignación (Is 26:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95574, 'spa', 'renovar, reparar, restaurar', 'Hacer nuevo de nuevo, restaurar o reparar, en dos registros que se solapan: restauración física de edificios e instalaciones cultuales (2 Cr 15:8; 24:4, 12), y renovación espiritual o cósmica (Sal 51:12, «renueva un espíritu recto dentro de mí»; Sal 104:30, Dios renovando la faz de la tierra; Lm 5:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95582, 'spa', 'nuevo, fresco', 'nuevo, fresco');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95590, 'spa', 'mes, período calendárico', 'Un mes como unidad del calendario: el período básico del calendario lunar hebreo. Con 260 de las 283 ocurrencias, es el sentido temporal no marcado que aparece desde la cronología del Diluvio (Gn 7:11, ''el segundo mes'') hasta la legislación festiva (Éx 12:2, ''el primero de vuestros meses'') y las fórmulas de datación histórica de Reyes y Crónicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95600, 'spa', 'luna nueva, fiesta lunar', 'La luna nueva como fenómeno astronómico y la observancia religiosa asociada: el primer día del mes celebrado como fiesta. Con 23 ocurrencias, este sentido se concentra en contextos cúlticos y proféticos: la narrativa de David y Jonatán (1 S 20:5, ''mañana es luna nueva''), el emparejamiento profético con los sábados (Is 1:14, ''vuestras lunas nuevas y fiestas solemnes'') y las regulaciones litúrgicas (Nm 28:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95631, 'spa', 'Mostrar, exhibir', 'Mostrar, exhibir o hacer visiblemente evidente a alguien, a menudo con un objeto directo que indica lo revelado y un objeto indirecto que indica el destinatario. Este sentido domina en Daniel 2, donde la urgencia se centra en mostrar al rey su propio sueño (Daniel 2:4, 6, 7, 9) — los sabios no deben solo contar sino demostrar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95633, 'spa', 'Declarar, proclamar', 'Declarar, proclamar o dar a conocer mediante anuncio verbal, enfatizando el acto comunicativo sobre la demostración visual. El decreto de Nabucodonosor de ''declarar'' las señales y maravillas que Dios ha hecho (Daniel 4:2) y la recomendación de la reina de que Daniel puede ''declarar'' interpretaciones (Daniel 5:12) ejemplifican este sentido orientado al discurso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95645, 'spa', 'Bóveda o círculo cósmico', 'Se refiere al límite circular o la bóveda del cosmos en tres contextos poéticos: Dios entronizado sobre el círculo de la tierra (Is 40:22), el círculo trazado en la creación (Pr 8:27), y el circuito de Dios por los cielos (Job 22:14). Las glosas multilingües (circle, círculo, vault) reflejan la imagen cosmológica antigua de un mundo acotado y abovedado. La palabra evoca la trascendencia divina sobre el orden creado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95646, 'spa', 'Proponer un enigma', 'Proponer o plantear un enigma, siempre con el acusativo cognado חִידָה. En Jueces 14:12-16, Sansón desafía a los invitados de su boda a resolver su acertijo sobre el león y la miel; el verbo capta el acto performativo de formular enigmas. En Ezequiel 17:2, pasa al discurso profético, donde Dios instruye a Ezequiel a ''proponer un enigma y hablar una parábola'', señalando un mensaje codificado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95647, 'spa', 'Declarar, dar a conocer', 'Declarar o dar a conocer algo mediante actos de habla formales y deliberados. Elihú lo usa frecuentemente para proclamar su opinión y conocimiento (Job 32:6, 10, 17; 36:2), al igual que Elifaz (Job 15:17). En Sal 19:3, el cielo nocturno ''declara conocimiento'' a las noches sucesivas. Su colorido arameo se adecúa al tono sapiencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95653, 'spa', 'Aldea de tiendas', 'Aldea de tiendas o pequeño asentamiento sin murallas, típicamente un conjunto de campamentos nómadas. Se encuentra casi siempre en el compuesto חַוֹּת יָאִיר (''Havot-Jair''), referido a los poblados que Jair conquistó en Galaad (Nm 32:41; Dt 3:14; Jue 10:4; 1 R 4:13). El término refleja un patrón de asentamiento seminómada: no una ciudad fortificada, sino un grupo de tiendas o chozas agrupadas por lazos de parentesco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95654, 'spa', 'Aldeas de Jaír', 'Designación geográfica para las aldeas de tiendas conquistadas y colonizadas por Jaír en Galaad. Números 32:41 registra el acto original de nombrarlas durante la conquista, mientras que Deuteronomio 3:14 y Jueces 10:4 confirman la perdurabilidad de esta designación para dichos asentamientos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95656, 'spa', 'espino, zarza, abrojo', 'Planta espinosa —zarza, abrojo o cardo— usada en imágenes proféticas y sapienciales. Aparece en la parábola de Joás donde el espino pretende dirigirse al cedro (2 R 14:9; 2 Cr 25:18), como señal de desolación (Os 9:6; Is 34:13), y en el memorable «lirio entre espinos» de Cantares 2:2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95659, 'spa', 'gancho, argolla, grillete', 'Gancho, argolla o grillete para capturar y conducir cautivos, nombrado por analogía con las espinas que atrapan y retienen. En 2 Crónicas 33:11, los asirios prenden a Manasés «con ganchos» (bachochim), un método humillante también representado en relieves asirios. Job 41:2 pregunta si alguien puede ponerle un gancho al Leviatán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95665, 'spa', 'Hilo, cordón, cuerda', 'Un hilo, cordón o línea de medir — una hebra delgada y flexible usada para atar, señalar o medir. En su forma más fina designa un simple hilo, la posesión más insignificante (Gn 14:23, «desde un hilo hasta una correa de sandalia»). Como cordón adquiere importancia práctica: el cordón escarlata de Rajab (Jos 2:18) se convierte en señal de liberación, y el cordón triple de Eclesiastés 4:12 ilustra la fortaleza de la unidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95671, 'spa', 'Los heveos, un grupo étnico cananeo enumerado entre las naciones preisraelitas ''', 'Los heveos, un grupo étnico cananeo enumerado entre las naciones preisraelitas ''engendradas'' por Canaán en la Tabla de las Naciones (Gn 10:17; 1 Cr 1:15). Aparecen en prácticamente todos los catálogos de conquista (Éx 3:8; 23:23; Dt 7:1; Jos 3:10; 12:8). Figuras heveas específicas incluyen a Siquem hijo de Hamor (Gn 34:2) y los gabaonitas que obtuvieron un pacto mediante engaño (Jos 9:7; 11:19). Salomón luego sometió a sus descendientes a trabajos forzados (1 R 9:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95683, 'spa', 'Havilá (nombre propio)', 'El nombre propio Havilá, que designa una tierra célebre por su oro (Gn 2:11) y pueblos en la Tabla de las Naciones descendientes tanto de Cus (Gn 10:7) como de Joctán (Gn 10:29). La doble ubicación genealógica podría reflejar la amplia extensión geográfica que abarcaba el nombre, posiblemente partes de Arabia o África oriental. Las variantes en español (Havilá, Javila) reflejan distintas tradiciones de transliteración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95688, 'spa', 'Pual/Hofal', 'Pual/Hofal: ser dado a luz/nacer');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95689, 'spa', 'Qal', 'Qal: girar/arremolinarse');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95690, 'spa', 'Qal', 'Qal: temblar/estremecerse de miedo');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95692, 'spa', 'Qal', 'Qal: retorcerse de dolor/angustia');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95693, 'spa', 'Piel', 'Piel: dar a luz/hacer nacer');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95695, 'spa', 'Qal', 'Qal: danzar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95696, 'spa', 'Qal/Hitpael', 'Qal/Hitpael: esperar/aguardar pacientemente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95699, 'spa', 'Qal', 'Qal: ser herido/traspasado');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95705, 'spa', 'Qal', 'Qal: estar de parto/sufrir dolores de parto');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95715, 'spa', 'Uso enigmático en Lamentaciones 4', 'Uso enigmático en Lamentaciones 4:6, de significado incierto en el contexto del juicio sobre Sodoma y Jerusalén; las traducciones varían entre ''se posaron'' y agonía prolongada, lo que sugiere posible corrupción textual o un empleo sin otro testimonio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95727, 'spa', 'Forma problemática del Ketiv en Jeremías 4', 'Forma problemática del Ketiv en Jeremías 4:19 donde el profeta clama de angustia ante el juicio venidero; el Qeré sugiere una lectura diferente y el sentido exacto es debatido — ya sea retorcerse de dolor (sentido 1), temblar de miedo (sentido 2) u otra cosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95744, 'spa', 'Arena usada predominantemente en símiles de cantidad innumerable (''como la arena', 'Arena usada predominantemente en símiles de cantidad innumerable (''como la arena del mar'') — la promesa abrahámica (Gn 22:17; 32:12), hordas militares (Jue 7:12; 1 S 13:5) y abundancia (Gn 41:49). El uso literal es raro: Éxodo 2:12, Jeremías 5:22. Las glosas multilingües convergen uniformemente: español ''arena'', francés ''sable'', alemán ''Sand'', confirmando un único sustantivo concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95753, 'spa', 'Color pardo oscuro', 'De color pardo oscuro o negro, usado exclusivamente de ovejas y cabras en la división del rebaño entre Jacob y Labán (Gn 30:32-40). Jacob reclama todo cordero חוּם del rebaño como su paga, distinguiendo estos animales oscuros de los manchados y moteados. El término es puramente descriptivo de un color animal natural, sin connotaciones morales, reflejando un tono terroso y cálido propio del vocabulario pastoril.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95754, 'spa', 'muralla, fortificación', 'Muralla defensiva perimetral de una ciudad: la imponente fortificación de piedra que circundaba un asentamiento antiguo, sirviendo tanto de protección militar como de delimitación cívica. Aparece en la caída de Jericó (Jos 6:5, 20), la fuga de Rahab (Jos 2:15), el asedio de Rabá (2 S 11:20-21) y el emblemático proyecto de reconstrucción de Nehemías (Neh 2:17; 12:27). Proféticamente, una muralla derribada señala juicio divino (Ez 26:9-10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95789, 'spa', 'Perdonar o abstenerse de destruir — el acto de retener el castigo, la violencia ', 'Perdonar o abstenerse de destruir — el acto de retener el castigo, la violencia o la ejecución del juicio. David ''perdonó'' la vida de Saúl cuando cortó su manto en vez de matarlo (1 S 24:10), Isaías declara que los arcos babilónicos ''no perdonarán'' a los niños (Is 13:18), y Ezequiel expresa repetidamente la resolución de Dios de no perdonar a Jerusalén (Ez 5:11; 7:4, 9; 8:18; 9:5, 10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95790, 'spa', 'Sentir piedad o tener compasión — la respuesta emocional de misericordia ante el', 'Sentir piedad o tener compasión — la respuesta emocional de misericordia ante el sufrimiento o la vulnerabilidad de alguien. Las fórmulas deuteronómicas ordenan ''tu ojo no tendrá piedad'' del transgresor del pacto (Dt 7:16; 13:8; 19:13, 21; 25:12), implicando que la compasión natural debe ser superada por la fidelidad al pacto. Ezequiel 16:5 dice que ningún ojo ''tuvo compasión'' de la Jerusalén infante, echada al campo abierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95800, 'spa', 'Mirar con pesar o sentir pérdida reluctante por algo valioso — un sentimiento de', 'Mirar con pesar o sentir pérdida reluctante por algo valioso — un sentimiento de nostalgia por lo que debe ser entregado. En Génesis 45:20, José dice a sus hermanos que su ojo no ''mire con pesar'' las posesiones dejadas en Canaán, porque lo mejor de Egipto les espera. La construcción es paralela a los otros modismos del ojo pero cambia de misericordia hacia personas a apego hacia cosas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95804, 'spa', 'Costa, ribera', 'La costa o ribera del mar — una franja de tierra al borde del agua. Las siete apariciones usan la forma constructa (חוֹף + sustantivo), vinculando estrechamente este término con su referente geográfico. La bendición de Jacob a Zabulón (Gn 49:13) lo emplea dos veces — «costa de mares» y «costa de navíos» — trazando la imagen de un territorio tribal marítimo. El término se utiliza también para delimitar fronteras de la Tierra Prometida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95811, 'spa', 'exterior, espacio de afuera', 'El exterior, espacio fuera de los muros, la puerta o el límite de un edificio, campamento o ciudad. Se usa con preposiciones (מִחוּץ, ''desde afuera''; אֶל־חוּץ, ''hacia afuera''; בַּחוּץ, ''en el exterior'') para expresar ubicación o dirección respecto a un recinto. Noé envía al cuervo ''afuera'' del arca; los leprosos son puestos ''fuera del campamento'' (Lv 13:46); la sangre se derrama ''fuera'' del santuario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95815, 'spa', 'calle, plaza pública', 'Calles, plazas, espacios públicos abiertos: la forma plural (חוּצוֹת) que designa las vías dentro de una zona habitada donde se desarrolla la vida comunitaria. El lamento de David prohíbe anunciar la muerte de Saúl ''en las calles de Ascalón'' (2 S 1:20); la Sabiduría clama ''en las calles'' (Pr 1:20); los niños juegan ''en las calles de Jerusalén'' (Zac 8:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95833, 'spa', 'campo abierto', 'Campo abierto, campiña: el espacio más allá de todo asentamiento, la extensión rural frente a la zona habitada. Job 5:10 habla de Dios que envía aguas ''sobre los campos abiertos'' (חוּצוֹת), y Proverbios 8:26 hace referencia a Dios creando antes de que existieran ''los espacios abiertos'' de la tierra. Este sentido extiende el límite interior/exterior del edificio o campamento a la ciudad misma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95834, 'spa', 'aparte de, fuera de', 'Uso aparentemente adverbial o preposicional que significa ''fuera de'' en el sentido de ''aparte de, excepto''. Eclesiastés 2:25 pregunta ''¿quién comerá o quién se gozará fuera de él (חוּץ מִמֶּנִּי)?''. El español ''fuera de'' conserva la metáfora espacial: estar ''fuera'' de la provisión de alguien es carecer de ella por completo. Esta única ocurrencia puede representar un blanqueamiento semántico del sentido locativo básico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95851, 'spa', 'Hur (nombre propio)', 'El nombre propio masculino Hur (חוּר), llevado por múltiples figuras bíblicas: (a) el compañero de Moisés y Aarón que sostuvo las manos de Moisés en Refidim (Éxodo 17:10, 12; 24:14), (b) el abuelo judahita del artesano del tabernáculo Bezaleel (Éxodo 31:2; 35:30; 1 Crónicas 2:19-20, 50; 4:1, 4), (c) un rey de Madián muerto junto con Balaam (Números 31:8; Josué 13:21), y (d) un oficial postexílico (Nehemías 3:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95854, 'spa', 'Agujero, abertura, cavidad', 'Un agujero, abertura o cavidad en una superficie o cuerpo, abarcando desde aperturas hechas por el hombre hasta oquedades naturales e incluso cuencas anatómicas. Aparece en contextos notablemente variados: un agujero cortado en la tapa de un cofre para las ofrendas del templo (2 R 12:9), la abertura de una puerta por la que el amado extiende su mano (Cnt 5:4), un boquete en la pared del templo que revela abominaciones ocultas (Ez 8:7) y cuevas rocosas usadas como escondite (1 S 14:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95865, 'spa', 'Juram', 'Nombre propio Juram (Hiram), que designa tanto al rey de Tiro aliado de David y Salomón para el proyecto del Templo (1 Cr 14:1; 2 Cr 2:3) como al maestro artesano del bronce enviado por dicho rey (2 Cr 2:13; 4:11). Las variantes Hiram/Juram reflejan diferencias ortográficas y dialectales en la transmisión, no distinciones semánticas. Las doce apariciones se concentran en la narrativa del Templo del Cronista.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95871, 'spa', 'Apresurarse, darse prisa (Qal intransitivo)', 'Apresurarse, darse prisa (Qal intransitivo): moverse con urgencia. Se usa para personas que actúan rápidamente, ya sea en obediencia (Sal 119:60), disposición militar (Núm 32:17) o figuradamente de pies que se apresuran al engaño (Job 31:5). La raíz aparece en el nombre profético Maher-Shalal-Hash-Baz, señalando la rapidez del juicio venidero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95872, 'spa', 'Hacer apresurarse, acelerar (Hifil causativo)', 'Hacer apresurarse, acelerar (Hifil causativo): hacer que algo suceda rápidamente, acelerar un evento o resultado. Isaías 5:19 registra a burladores desafiando a Dios a ''apresurar su obra'', e Isaías 60:22 promete la aceleración divina ''a su tiempo''. En Jueces 20:37 la emboscada ''se apresuró'' en su ataque.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95886, 'spa', 'Husai (nombre propio)', 'El nombre propio hebreo Husai (חוּשַׁי), que identifica principalmente a Husai el arquita, confidente y consejero de David que desempeñó un papel decisivo en la rebelión de Absalón al socavar el astuto consejo militar de Ahitofel (2 Samuel 15:32-17:16). Llamado ''amigo de David'' (רֵעֶה דָוִד), un título que puede designar un cargo formal en la corte. También referenciado como padre de Baana, uno de los doce gobernadores de distrito de Salomón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95892, 'spa', 'Rey edomita', 'חוּשָׁם / חֻשָׁם, rey de Edom procedente de la tierra de los temanitas, registrado en las listas genealógicas de Génesis 36:34–35 y 1 Crónicas 1:45–46. Sucedió a Jobab hijo de Zera y fue sucedido por Hadad hijo de Bedad. Las dos vocalizaciones ligeramente distintas se refieren al mismo individuo dentro de las listas de reyes edomitas anteriores a Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95893, 'spa', 'Sello, anillo de sellar', 'Un sello o anillo de sellar (חוֹתָם / חֹתָם) — un objeto personal de autenticación y autoridad. Físicamente, podía colgarse de un cordón alrededor del cuello (Génesis 38:18) o llevarse en la mano derecha (Jeremías 22:24). Sus usos abarcan lo práctico — estampar documentos reales (1 Reyes 21:8) y grabar piedras sacerdotales con la técnica descrita como ''grabados de sello'' (Éxodo 28:11, 39:6) — y lo figurado, donde Dios mismo es comparado con un sello.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95899, 'spa', 'Ver, contemplar (activo)', 'Ver, contemplar (activo): ver, contemplar o percibir activamente, especialmente en sueños y visiones proféticas. Sentido dominante (30 ocurrencias) que impregna las narrativas apocalípticas de Daniel y aparece una vez en Esdras 4:14. La forma participial חָזֵה se emplea característicamente en construcciones perifrásticas de visión continua: ''estaba viendo'' (Dn 7:4, 7, 9). Nabucodonosor contempla la gran estatua en su sueño (Dn 2:31), Daniel ve las cuatro bestias surgir del mar (Dn 7:2-7) y al Anciano de Días tomar su trono (Dn 7:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95908, 'spa', 'Ser visto, ser visible (pasivo)', 'Ser visto, ser visible (pasivo): ser visto, aparecer visible ante otros — sentido pasivo que indica que algo es percibido en vez de percibir. Única ocurrencia (Dn 3:19) que usa el participio pasivo para describir cómo la expresión facial de Nabucodonosor cambió visiblemente cuando se enfureció contra Sadrac, Mesac y Abed-nego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95909, 'spa', 'El nombre propio Hazael, el rey arameo de Damasco (mediados del siglo IX a', 'El nombre propio Hazael, el rey arameo de Damasco (mediados del siglo IX a.C.) que se apoderó del trono mediante regicidio (2 R 8:15), devastó los territorios de Israel (2 R 10:32; 13:3, 22) y amenazó a Judá (2 R 12:17-18). Las transliteraciones varían — inglés ''Hazael'', español ''Jazael/Hazael'', francés ''Hazaël'' — pero todas identifican a la misma figura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95913, 'spa', 'ver, percibir visualmente', 'ver, percibir visualmente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95915, 'spa', 'mirad, contemplad (imperativo)', 'mirad, contemplad (imperativo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95919, 'spa', 'contemplar, mirar con reverencia', 'contemplar, mirar con reverencia');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95922, 'spa', 'ver proféticamente, tener visiones', 'ver proféticamente, tener visiones');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95943, 'spa', 'Ocurrencia difícil en Job 23', 'Ocurrencia difícil en Job 23:9 donde Job dice que no puede percibir ni discernir la presencia de Dios a pesar de buscarle: ''me vuelvo a la derecha pero no lo alcanzo''. El contexto sugiere una percepción frustrada o fallida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95953, 'spa', 'Pecho, pechuga', 'La porción del pecho de un animal sacrificial separada como ofrenda mecida y designada como la parte sacerdotal. Usado solo en la legislación sacerdotal: la ofrenda de instalación (Éxodo 29:26-27; Levítico 8:29), la ofrenda de paz (Levítico 7:30-31, 34; 9:20-21; 10:14-15) y el sacrificio del nazareo (Números 6:20; cf. Números 18:18). Siempre aparece junto al ritual de mecimiento, marcándolo como término tanto anatómico como litúrgico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95958, 'spa', 'Persona que recibe visiones o revelaciones divinas, funcionando como título sust', 'Persona que recibe visiones o revelaciones divinas, funcionando como título sustantivado para figuras proféticas. Sinónimo de רֹאֶה y נָבִיא pero con énfasis en la dimensión visual de la experiencia profética. Aplicado a profetas nombrados como Gad (2 S 24:11; 1 Cr 21:9), Amós (Am 7:12) e Iddo (2 Cr 9:29), así como a cantores del templo — Hemán (1 Cr 25:5), Asaf (2 Cr 29:30), Jedutún (2 Cr 35:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95963, 'spa', 'Un pacto o acuerdo vinculante entre partes, atestiguado solo en Isaías 28', 'Un pacto o acuerdo vinculante entre partes, atestiguado solo en Isaías 28:15 donde se acusa a Israel de hacer un ''pacto con la muerte''. El español retiene interesantemente ''visión'', reflejando la ambigüedad interpretativa. La mayoría de los eruditos tratan esto como una raíz homónima distinta del sentido profético de ''vidente'', aunque el juego de palabras irónico — una ''visión'' falsa que se convierte en un ''pacto'' mortal — puede ser deliberado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95971, 'spa', 'Visión profética', 'Visión profética o revelación otorgada por Dios, significado dominante en todo el libro de Daniel. Las expresiones ''visiones de la noche'' (ḥezwē lēlyā, Dn 2:19; 7:2, 7, 13) y ''visiones de mi cabeza'' (ḥezwē rēʾšā, Dn 2:28; 4:2, 7, 10; 7:1, 15) las presentan como revelaciones sobrenaturales recibidas durante el sueño o en estado de éxtasis.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95973, 'spa', 'Apariencia externa', 'Apariencia o aspecto visible de algo, distinto de la experiencia profética interior. Se usa únicamente en Daniel 7:20, donde describe el aspecto imponente del cuerno pequeño cuya ''apariencia era mayor que la de sus compañeros''. El paso de revelación a aspecto físico tiene paralelo en el cognado hebreo ḥāzōn, que igualmente puede denotar una visión profética o un espectáculo percibido con los ojos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95977, 'spa', 'Visión profética', 'Visión profética: una visión profética o revelación divina recibida mediante percepción extática, que designa también el oráculo o mensaje profético resultante. Funciona en tres registros: como etiqueta genérica en los encabezados de libros proféticos (Is 1:1; Abd 1:1; Nah 1:1), enmarcando toda la obra como revelación divinamente comunicada; como experiencia visionaria específica en contextos narrativos, especialmente las visiones apocalípticas de Daniel (Dn 8:1-2, 13, 15, 17, 26); y como concepto abstracto en la literatura sapiencial — ''donde no hay visión, el pueblo se desenfrena'' (Pr 29:18). Lamentaciones 2:9 describe la dimensión más oscura del exilio: ''sus profetas no hallan visión de parte de YHWH''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95984, 'spa', 'Visión profética', 'Una visión profética u oráculo recibido por un vidente, como en Is 21:2 (''una visión dura me ha sido declarada'') e Is 29:11, donde el mensaje profético entero se ha vuelto como un documento sellado. El español y el francés traducen uniformemente ''visión'', reflejando el sentido profético nuclear vinculado al verbo חָזָה. En Dn 8:5, 8, describe el aspecto visible del cuerno prominente del macho cabrío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (95988, 'spa', 'Visión, revelación', 'Una visión o revelación profética: una experiencia sobrenatural que transmite verdad divina, recibida en estados de éxtasis o durante la noche. Su campo semántico abarca las experiencias visionarias nocturnas (Job 4:13; 20:8; 33:15, frecuentemente asociadas con sueños), los oráculos proféticos (2 S 7:17) y la promesa escatológica de que los jóvenes verán visiones (Jl 3:1). Zacarías 13:4 la emplea en tono de advertencia contra los falsos profetas.');